import { Metadata } from "next";
import { Suspense } from "react";
import { unstable_cache } from "next/cache";
import { getProducts, getCategories, getPopulatedCategoryFilter, deriveColors, deriveSizes } from "@/lib/products";
import { ShopPageClient } from "@/components/ui/miss-tokyo/ShopPageClient";
import { supabaseAdmin } from "@/lib/supabaseAdmin";

const getAutoDiscountRules = unstable_cache(
    async () => {
        const { data } = await supabaseAdmin
            .from("automatic_discounts")
            .select("id, title, discount_type, discount_value, applies_to, target_category_ids, target_product_ids, min_quantity, quantity_scope, min_order_amount")
            .eq("is_active", true);
        return data ?? [];
    },
    ["active-auto-discounts"],
    { revalidate: 300, tags: ["auto-discounts"] }
);

// Cache admin-controlled settings for 5 minutes — they change rarely and this
// fetch fires on every dynamic /shop render, contributing ~0.5-1s per invocation.
const getShopSettings = unstable_cache(
    async () => {
        const [paginationRes, mobileColsRes] = await Promise.all([
            supabaseAdmin
                .from("site_settings")
                .select("shop_pagination_type")
                .eq("id", "singleton")
                .maybeSingle(),
            supabaseAdmin
                .from("store_settings")
                .select("shop_mobile_cols")
                .eq("id", "default")
                .maybeSingle(),
        ]);
        return {
            paginationSetting: (paginationRes.data?.shop_pagination_type ?? "load_more") as "load_more" | "pagination",
            mobileCols: (Number(mobileColsRes.data?.shop_mobile_cols) || 2) as 1 | 2,
        };
    },
    ["shop-settings"],
    { revalidate: 300 }
);

export const revalidate = 60;

interface SearchParams {
    category?: string;
    sort?: string;
    color?: string;
    size?: string;
    min?: string;
    max?: string;
    page?: string;
    q?: string;
    sale?: string;
}

export async function generateMetadata({
    searchParams,
}: {
    searchParams: Promise<SearchParams>;
}): Promise<Metadata> {
    const params = await searchParams;
    const BASE = process.env.NEXT_PUBLIC_SITE_URL || "https://misstokyo.shop";

    if (params.category) {
        const { data: cat } = await supabaseAdmin
            .from("categories")
            .select("name, product_count")
            .eq("slug", params.category)
            .maybeSingle();
        if (cat) {
            return {
                title: `${cat.name} — Miss Tokyo`,
                description: `Shop ${cat.name} at Miss Tokyo. ${cat.product_count} styles available. New drops weekly.`,
                alternates: { canonical: `${BASE}/shop?category=${params.category}` },
            };
        }
    }

    return {
        title: "Shop — Miss Tokyo",
        description:
            "Browse 240+ styles — dresses, tops, sets, activewear and more. New drops weekly. Free delivery in Accra on orders over GH₵150.",
        alternates: { canonical: `${BASE}/shop` },
    };
}

export default async function ShopPage({
    searchParams,
}: {
    searchParams: Promise<SearchParams>;
}) {
    const params = await searchParams;
    // Role is resolved client-side to keep this page ISR-cacheable.
    // Wholesale users see public products on initial load; client-side auth
    // in ShopPageClient can upgrade the view after hydration if needed.
    const role: string | undefined = undefined;

    const [{ paginationSetting, mobileCols }, autoDiscountRules] = await Promise.all([
        getShopSettings().catch(() => ({ paginationSetting: "load_more" as const, mobileCols: 2 as const })),
        getAutoDiscountRules().catch(() => []),
    ]);

    const [{ products, total, minPrice, maxPrice }, allCategories] = await Promise.all([
        getProducts({
            category: params.category,
            sort:     params.sort,
            color:    params.color,
            size:     params.size,
            min:      params.min,
            max:      params.max,
            page:     params.page ? parseInt(params.page) : 1,
            q:        params.q,
            sale:     params.sale === "true",
        }, role),
        getCategories(role),
    ]);

    const categories = await getPopulatedCategoryFilter(allCategories);

    // Resolve category slug → name once (reused for both filter queries)
    let categoryName: string | null = null;
    let categoryId: string | null = null;
    if (params.category) {
        const { data: cat } = await supabaseAdmin
            .from("categories")
            .select("id, name")
            .eq("slug", params.category)
            .maybeSingle();
        categoryName = cat?.name
            ?? params.category.split("-").map((w: string) => w.charAt(0).toUpperCase() + w.slice(1)).join(" ");
        categoryId = cat?.id || null;
    }

    // Faceted filter queries:
    // • allColors = colors available within the current category + size selection
    // • allSizes  = sizes  available within the current category + color selection
    const buildBase = () =>
        supabaseAdmin.from("products").select("available_colors, available_sizes").eq("is_active", true);

    let colorsQ = buildBase();
    let sizesQ  = buildBase();

    if (categoryId && categoryName) {
        const orFilter = `category_type.ilike."${categoryName}",category_id.eq.${categoryId},category_ids.cs.{"${categoryId}"}`;
        colorsQ = colorsQ.or(orFilter) as typeof colorsQ;
        sizesQ  = sizesQ.or(orFilter) as typeof sizesQ;
    } else if (categoryName) {
        colorsQ = colorsQ.ilike("category_type", categoryName) as typeof colorsQ;
        sizesQ  = sizesQ.ilike("category_type",  categoryName) as typeof sizesQ;
    }
    if (params.sale === "true") {
        colorsQ = colorsQ.eq("is_sale", true) as typeof colorsQ;
        sizesQ  = sizesQ.eq("is_sale",  true) as typeof sizesQ;
    }
    // Colors are constrained by the active size filter
    if (params.size)  colorsQ = colorsQ.contains("available_sizes",  [params.size])  as typeof colorsQ;
    // Sizes are constrained by the active color filter
    if (params.color) sizesQ  = sizesQ.contains("available_colors", [params.color]) as typeof sizesQ;

    const [{ data: colorsData }, { data: sizesData }] = await Promise.all([colorsQ, sizesQ]);

    const toFilterRows = (rows: any[] | null) =>
        (rows || []).map((p: any) => ({ ...p, color_variants: null, size_variants: null }));

    const allColors = deriveColors(toFilterRows(colorsData) as any);
    const allSizes  = deriveSizes(toFilterRows(sizesData)  as any);

    const skeletonFallback = (
        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4 p-6">
            {Array.from({ length: 8 }).map((_, i) => (
                <div key={i} className="h-64 bg-gray-100 animate-pulse rounded-md" />
            ))}
        </div>
    );

    return (
        <Suspense fallback={skeletonFallback}>
            <ShopPageClient
                initialProducts={products}
                categories={categories}
                allColors={allColors}
                allSizes={allSizes}
                total={total}
                minPrice={minPrice}
                maxPrice={maxPrice}
                paginationType={paginationSetting}
                mobileCols={mobileCols}
                autoDiscountRules={autoDiscountRules}
            />
        </Suspense>
    );
}
